const staticData = $getWorkflowStaticData('global');
const runId = $json.runId;
const run = staticData.runs?.[runId];

let text = '';
let fetchError = null;

try {
  // PDFs are routed to 2nd-pass OCR now, so this node only sees HTML/CSV/JSON.
  // But handle kind=pdf gracefully in case routing changes.
  if ($json.kind === 'pdf') {
    // PDF arrived here unexpectedly (OCR.Space disabled). Just mark URL for 2nd-pass.
    if (run) {
      run._harvested = run._harvested || [];
      if (!run._harvested.includes($json.url)) run._harvested.push($json.url);
    }
    text = '[PDF rerouted to 2nd-pass OCR]';
  } else {
    const fetchNode = $node['Fetch Text (HTML/CSV/JSON)'];
    if (fetchNode) {
      const raw = fetchNode.json;
      text = (typeof raw === 'string' ? raw : (raw?.body || raw?.data || JSON.stringify(raw))).slice(0, 80000);
    } else {
      const raw = $input.first().json;
      text = (typeof raw === 'string' ? raw : (raw?.body || raw?.data || JSON.stringify(raw))).slice(0, 80000);
    }
  }
} catch(e) {
  fetchError = e.message;
}

// CRITICAL FIX: Harvest hrefs from RAW HTML BEFORE stripping tags.
// The original code harvested AFTER stripping, which removed all href attributes first.
const harvested = [];
if ($json.kind === 'html' && text) {
  const hrefRe = /href\s*=\s*["']([^"'#?][^"']*)["']/gi;
  let m;
  while ((m = hrefRe.exec(text)) !== null) {
    const href = m[1].trim();
    if (!href || href.startsWith('javascript:') || href.startsWith('mailto:')) continue;
    try {
      const abs = new URL(href, $json.url).toString();
      const lu = abs.toLowerCase();
      if (
        lu.endsWith('.pdf') || lu.endsWith('.csv') || lu.endsWith('.xlsx') ||
        lu.includes('licit') || lu.includes('contrat') || lu.includes('presup') ||
        lu.includes('boletin') || lu.includes('ordenanza') || lu.includes('decreto') ||
        lu.includes('resoluci') || lu.includes('transparenc') || lu.includes('compras')
      ) {
        harvested.push(abs);
      }
    } catch(e) {}
  }
}

// NOW strip HTML tags (after harvesting)
if ($json.kind === 'html' && text) {
  text = text
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 60000);
}

if (run) {
  run.step = 'fetch';
  run.progress = Math.min(55, (run.progress || 18) + 1);
  run.logs.push({ t: new Date().toISOString(), m: `Fetched ${($json.kind||'').toUpperCase()} ${$json.url} | harvested ${harvested.length} links${fetchError ? ' (ERROR: ' + fetchError + ')' : ''}` });
  run.docs = run.docs || [];
  run.docs.push({
    url: $json.url,
    kind: $json.kind,
    fetched_at: new Date().toISOString(),
    text_preview: (text || '').slice(0, 8000),
    has_text: (!!text && !fetchError) || $json.kind === 'pdf',
    error: fetchError || null
  });
  run._harvested = run._harvested || [];
  for (const h of harvested) {
    if (!run._harvested.includes(h)) run._harvested.push(h);
  }
  // Cap at 80 to give room for 2024 boletines + anything discovered
  run._harvested = run._harvested.slice(0, 80);
}

return [{ json: { ...$json, text } }];
